#include "(CurrentProject)/js/personaliza/personaWizard.js"

// ------------------------------------
// Cargar proyectos en combobox
// ------------------------------------

// Atrapar el formulario donde están los controles
var formulario = theRoot.dataView();

// Preparar los arrays
var proyectosInfo = [];
var proyectosAlias = [];
var proyectosId = [];
getProyectosHeredadosInfo(theApp.mainProjectInfo(), proyectosInfo, proyectosAlias, proyectosId);

// Se preparan el combobox para cargar los proyectos
var controlProyecto = formulario.control("TAB_PRY");

// Limpiar el contenido de los controles
controlProyecto.clear();

// Cargar los proyectos en los controles
for(numProyecto in proyectosInfo)
{
	// Se cargan solo proyectos de datos
	if (proyectosInfo[numProyecto].type() == VProjectInfo.TypeDat)
	{
		controlProyecto.addItem(proyectosInfo[numProyecto].name(), proyectosInfo[numProyecto].alias());
	};
};

controlProyecto.setCurrentIndex(controlProyecto.findData(theRegisterIn.fieldToString("TAB_PRY")));

#include "(CurrentProject)/js/personaliza/personaWizard.js"

// -------------------------------------------------
// Limpiar la tabla en memoria de subobjetos
// -------------------------------------------------
var listaObjetos = new VRegisterList(theRoot);
listaObjetos.setTable("sygemat_corralon_dat/API_CTR_W");
listaObjetos.load("ID", []);
listaObjetos.remove(listaObjetos);

// ---------------------------------------------------------------
// Leer el proyecto y la tabla si no está marcado sin tabla
// ---------------------------------------------------------------
var formularioPadre = theRoot.dataView();
var separador       = formularioPadre.control("SEP");
var controlSinTabla = formularioPadre.control("SIN_TAB");
if (controlSinTabla.checked == false)
{
	// --------------------------------------------------------------------------------------------------
	// Si no está marcado sin tabla se cargan los registros de campos, procesos y búsquedas
	// --------------------------------------------------------------------------------------------------

	// Atrapar los subformularios donde están los subobjetos
	var formularioCampos    = separador.form("sygemat_corralon_app/API_SEG_W_CAM");
	var formularioProcesos  = separador.form("sygemat_corralon_app/API_SEG_W_PRO");
	var formularioBusquedas = separador.form("sygemat_corralon_app/API_SEG_W_BUS");

	// Limpiar las rejillas (Por si no se cargan registros)
	if (formularioCampos)
	{
		var rejillaCampos = formularioCampos.control("LST");
		rejillaCampos.clear();
	};

	if (formularioProcesos)
	{
		var rejillaProcesos = formularioProcesos.control("LST");
		rejillaProcesos.clear();
	};

	if (formularioBusquedas)
	{
		var rejillaBusquedas = formularioBusquedas.control("LST");
		rejillaBusquedas.clear();
	};

	// Leer el proyecto seleccionado
	var controlProyecto   = formularioPadre.control("TAB_PRY");
	var controlTabla      = formularioPadre.control("TAB_ID");
	var proyectoPrincipal = theApp.mainProjectInfo();
	var proyectoInfo      = theApp.projectInfo(controlProyecto.itemData(controlProyecto.currentIndex));
	if ((proyectoInfo) && (controlTabla.itemData(controlTabla.currentIndex)))
	{	
		// Leemos la tabla seleccionada		
		var tablaInfo = proyectoInfo.objectInfo(VObjectInfo.TypeTable, controlTabla.itemData(controlTabla.currentIndex));
		if (tablaInfo)
		{	
			// Se abre transacción si no existe
			transCurso = theRoot.existTrans();
			if (transCurso == false)
			{
				var transNueva = theRoot.beginTrans("Creando objetos del API key de la tabla en memoria");
			};

			if (transCurso || transNueva)
			{
				// -------------------------------------------------------------------------
				// Generar los registros correspondientes a los campos de la tabla
				// -------------------------------------------------------------------------
				var tipoSubobjetos          = VObjectInfo.TypeField;
				var subobjetosSeleccionados = theRegisterIn.fieldToString("CAM").split(",");
				var numObjetos              = tablaInfo.subObjectCount(tipoSubobjetos);

				for (var numObjeto = 0; numObjeto < numObjetos; numObjeto++)
				{
					var objeto = tablaInfo.subObjectInfo(tipoSubobjetos, numObjeto);			
					if (objeto.isPrivate() == false)
					{	
						// Se preparan los datos
						var objetoId   = objeto.id();
						var objetoName = objeto.name();

						// Se crear el registro en la tabla en memoria
						var registro = new VRegister(theRoot);
						registro.setTable("sygemat_corralon_dat/API_CTR_W");
						registro.setField("CTL_ID"     , objetoId);
						registro.setField("NAME"       , objetoName);
						registro.setField("POS"        , numObjeto);
						registro.setField("PRS_API_TIP", "C");
						registro.addRegister();
						listaObjetos.append(registro);

						// Añadir el registro a la lista y marcarlo como seleccionado si procede
						rejillaCampos.append(registro);						
						if (subobjetosSeleccionados.indexOf(objetoId) != -1)
						{
							rejillaCampos.addToMultiSelection(registro);
						};
					};
				};

				// -----------------------------------------------------------------------------------------------------
				// Generar los registros correspondientes a los procesos con la tabla destino seleccionada
				// -----------------------------------------------------------------------------------------------------
				var tipoSubobjetos          = VObjectInfo.TypeProcess;
				var subobjetosSeleccionados = theRegisterIn.fieldToString("PRO").split(",");
				var numObjetos              = proyectoPrincipal.allObjectCount(tipoSubobjetos);

				for (var numObjeto = 0; numObjeto < numObjetos; numObjeto++)
				{
					var objeto = proyectoPrincipal.allObjectInfo(tipoSubobjetos, numObjeto);
					if ((objeto.isPrivate() == false) && (objeto.outputTable().idRef() == tablaInfo.idRef()))
					{	
						// Se preparan los datos
						var objetoId   = objeto.idRef();
						var objetoName = objeto.name();

						// Se crear el registro en la tabla en memoria
						var registro = new VRegister(theRoot);
						registro.setTable("sygemat_corralon_dat/API_CTR_W");
						registro.setField("CTL_ID"     , objetoId);
						registro.setField("NAME"       , objetoName);
						registro.setField("POS"        , numObjeto);
						registro.setField("PRS_API_TIP", "P");
						registro.addRegister();
						listaObjetos.append(registro);

						// Añadir el registro a la lista y marcarlo como seleccionado si procede
						rejillaProcesos.append(registro);						
						if (subobjetosSeleccionados.indexOf(objetoId) != -1)
						{
							rejillaProcesos.addToMultiSelection(registro);
						};
					};
				};

				// -----------------------------------------------------------------------------------------------------
				// Generar los registros correspondientes a las búsqueda con la tabla destino seleccionada
				// -----------------------------------------------------------------------------------------------------
				var tipoSubobjetos          = VObjectInfo.TypeQuery;
				var subobjetosSeleccionados = theRegisterIn.fieldToString("BUS").split(",");
				var numObjetos              = proyectoPrincipal.allObjectCount(tipoSubobjetos);

				for (var numObjeto = 0; numObjeto < numObjetos; numObjeto++)
				{
					var objeto = proyectoPrincipal.allObjectInfo(tipoSubobjetos, numObjeto);			
					if ((objeto.isPrivate() == false) && (objeto.outputTable().idRef() == tablaInfo.idRef()))
					{	
						// Se preparan los datos
						var objetoId   = objeto.idRef();
						var objetoName = objeto.name();

						// Se crear el registro en la tabla en memoria
						var registro = new VRegister(theRoot);
						registro.setTable("sygemat_corralon_dat/API_CTR_W");
						registro.setField("CTL_ID"     , objetoId);
						registro.setField("NAME"       , objetoName);
						registro.setField("POS"        , numObjeto);
						registro.setField("PRS_API_TIP", "B");
						registro.addRegister();
						listaObjetos.append(registro);

						// Añadir el registro a la lista y marcarlo como seleccionado si procede
						rejillaBusquedas.append(registro);						
						if (subobjetosSeleccionados.indexOf(objetoId) != -1)
						{
							rejillaBusquedas.addToMultiSelection(registro);
						};
					};
				};

				// Se cierra la transacción si se creó una nueva
				if (transNueva)
				{
					theRoot.commitTrans();
				};
			};
		};		
	};
}
else
{
	// -------------------------------------------------------------------------------- 
	// Si  está marcado sin tabla se cargan los registros procesos sin origen
	// --------------------------------------------------------------------------------

	// Atrapar los subformularios donde están los subobjetos
	var formularioProcesos  = separador.form("sygemat_corralon_app/API_SEG_W_PRO");

	// Limpiar las rejillas (Por si no se cargan registros)
	var rejillaProcesos  = formularioProcesos.control("LST");
	rejillaProcesos.clear();

	// Leer el proyecto seleccionado
	var controlProyecto   = formularioPadre.control("TAB_PRY");
	var proyectoPrincipal = theApp.mainProjectInfo();

	// Se abre transacción si no existe
	transCurso = theRoot.existTrans();
	if (transCurso == false)
	{
		var transNueva = theRoot.beginTrans("Creando objetos del API key sin tabla en memoria");
	};

	if (transCurso || transNueva)
	{
		// -----------------------------------------------------------------------------------------------------
		// Generar los registros correspondientes a los procesos con la tabla destino seleccionada
		// -----------------------------------------------------------------------------------------------------
		var tipoSubobjetos          = VObjectInfo.TypeProcess;
		var subobjetosSeleccionados = theRegisterIn.fieldToString("PRO").split(",");
		var numObjetos              = proyectoPrincipal.allObjectCount(tipoSubobjetos);

		for (var numObjeto = 0; numObjeto < numObjetos; numObjeto++)
		{
			var objeto = proyectoPrincipal.allObjectInfo(tipoSubobjetos, numObjeto);
			if ((objeto.isPrivate() == false) && (objeto.outputType() == VObjectInfo.IONone))
			{	
				// Se preparan los datos
				var objetoId   = objeto.idRef();
				var objetoName = objeto.name();

				// Se crear el registro en la tabla en memoria
				var registro = new VRegister(theRoot);
				registro.setTable("sygemat_corralon_dat/API_CTR_W");
				registro.setField("CTL_ID"     , objetoId);
				registro.setField("NAME"       , objetoName);
				registro.setField("POS"        , numObjeto);
				registro.setField("PRS_API_TIP", "P");
				registro.addRegister();
				listaObjetos.append(registro);

				// Añadir el registro a la lista y marcarlo como seleccionado si procede
				rejillaProcesos.append(registro);						
				if (subobjetosSeleccionados.indexOf(objetoId) != -1)
				{
					rejillaProcesos.addToMultiSelection(registro);
				};
			};
		};

		// Se cierra la transacción si se creó una nueva
		if (transNueva)
		{
			theRoot.commitTrans();
		};
	};
};

#include "(CurrentProject)/js/personaliza/personaWizard.js"

// -----------------------------------
// Cargar las tablas del proyecto
// -----------------------------------

// Atrapar el formulario donde están los controles
var formulario = theRoot.dataView();

// Leer el proyecto seleccionado
var controlProyecto = formulario.control("TAB_PRY");
if (controlProyecto)
{
	var proyectoInfo = theApp.projectInfo(controlProyecto.itemData(controlProyecto.currentIndex));
};

// Cargar objetos en el combobox
var objetosInfo = getObjetosProyectoTipoInfo(proyectoInfo, VObjectInfo.TypeTable);
var controlObjeto = formulario.control("TAB_ID");
if (controlObjeto)
{
	// Se limpia el contenido antes de añadir el nuevo
	controlObjeto.clear();

	// Se añaden los objetos que no sean privados a un array para ordenarlo y añadirlos al listbox
	var objetos = [];
	for(numObjeto in objetosInfo)
	{
		if (objetosInfo[numObjeto].isPrivate() == false)
		{
			objetos.push(objetosInfo[numObjeto].id() + ":" + objetosInfo[numObjeto].name()); 
		};
	};

	// Se ordenan los objetos por ID antes de incluirlos en el listbox
	objetos.sort();
	for(numObjeto in objetos)
	{
		var objeto = objetos[numObjeto].split(":");
		controlObjeto.addItem(objeto[0] + "  (" + objeto[1] + ")", objeto[0]);
	};

	controlObjeto.setCurrentIndex(controlObjeto.findData(theRegisterIn.fieldToString("TAB_ID")));
};

// -----------------------------------------------
// Pasar el valor de los combobox a campos
// -----------------------------------------------

// Atrapar el formulario donde están los controles
var formulario = theRoot.dataView();

// Proyecto del proceso de generación de fichero
var control = formulario.control("TAB_PRY");
if (control.itemData(control.currentIndex))
{
	theRegisterIn.setField("TAB_PRY", control.itemData(control.currentIndex));
};

// Objeto del proceso de generación de fichero
var control = formulario.control("TAB_ID");
if (control.itemData(control.currentIndex))
{
	theRegisterIn.setField("TAB_ID", control.itemData(control.currentIndex));
};

#include "(CurrentProject)/js/interface/ocultarMostrarTab.js"

// ----------------------------------------------------------------------------
// Mostrar u ocultar pestaña en función del valor del check sin tabla
// ----------------------------------------------------------------------------

// Se actúa en función del estado del check
if (theRoot.dataView().control("SIN_TAB").checked == true)
{
	// Si está marcado se ocultan los subformularios de campos y búsquedas si están visibles
	quitarTab("SEP", "sygemat_corralon_app/API_SEG_W_CAM");
	quitarTab("SEP", "sygemat_corralon_app/API_SEG_W_BUS");
}
else
{
	// Si no está marcado se hace visibles los subformularios de campos y búsquedas
	insertarTab("SEP", "sygemat_corralon_app/API_SEG_W_CAM", "sygemat_corralon_app/API_SEG_W_PRO", 0 );
	insertarTab("SEP", "sygemat_corralon_app/API_SEG_W_BUS", "sygemat_corralon_app/API_SEG_W_PRO", 1 );
};
